using System.ComponentModel;using System.Globalization;using System.Text;using System.Text.Json;
namespace BookManager;
public class MainForm:Form{
TextBox id=new(),title=new(),author=new(),category=new(),qty=new(),price=new(),search=new();PictureBox cover=new(){Width=135,Height=150,SizeMode=PictureBoxSizeMode.Zoom,BorderStyle=BorderStyle.FixedSingle};DataGridView grid=new();BindingList<BookModel> books=new();BindingSource bs=new();ErrorProvider ep=new();ToolStripStatusLabel count=new(),value=new(),clock=new();BookModel? selected;string coverPath="";System.Windows.Forms.Timer timer=new(){Interval=1000};
public MainForm(){Text="Book Manager - Quản lý tài liệu sách";Width=1250;Height=780;MinimumSize=new Size(950,600);Build();bs.DataSource=books;grid.DataSource=bs;books.ListChanged+=(_,_)=>UpdateStatus();books.Add(new(){BookId="S001",Title="Lập trình C# cơ bản",Author="Nguyễn Văn A",Category="Công nghệ",Quantity=10,UnitPrice=95000});books.Add(new(){BookId="S002",Title="Cấu trúc dữ liệu",Author="Trần Văn B",Category="Công nghệ",Quantity=7,UnitPrice=120000});timer.Tick+=(_,_)=>clock.Text="Thời gian: "+DateTime.Now.ToString("dd/MM/yyyy HH:mm:ss");timer.Start();UpdateStatus();}
void Build(){ep.ContainerControl=this;var menu=new MenuStrip();var file=new ToolStripMenuItem("File");file.DropDownItems.Add("Mở file CSV",null,(_,_)=>Import());file.DropDownItems.Add("Lưu file CSV",null,(_,_)=>Export());file.DropDownItems.Add("Thoát",null,(_,_)=>Close());var edit=new ToolStripMenuItem("Edit");edit.DropDownItems.Add("Thêm",null,(_,_)=>AddBook());edit.DropDownItems.Add("Xóa",null,(_,_)=>DeleteBook());edit.DropDownItems.Add("Tìm kiếm",null,(_,_)=>search.Focus());menu.Items.AddRange(new ToolStripItem[]{file,edit});MainMenuStrip=menu;Controls.Add(menu);var tool=new ToolStrip{Dock=DockStyle.Top};tool.Items.Add(new ToolStripButton("📂 Mở file",null,(_,_)=>Import()));tool.Items.Add(new ToolStripButton("💾 Lưu CSV",null,(_,_)=>Export()));tool.Items.Add(new ToolStripButton("➕ Thêm mới",null,(_,_)=>AddBook()));Controls.Add(tool);var status=new StatusStrip();status.Items.Add(count);status.Items.Add(new ToolStripStatusLabel{Spring=true});status.Items.Add(value);status.Items.Add(new ToolStripStatusLabel{Spring=true});status.Items.Add(clock);Controls.Add(status);var root=new TableLayoutPanel{Dock=DockStyle.Fill,Padding=new Padding(8),RowCount=2};root.RowStyles.Add(new(SizeType.Absolute,245));root.RowStyles.Add(new(SizeType.Percent,100));Controls.Add(root);root.BringToFront();var top=new TableLayoutPanel{Dock=DockStyle.Fill,ColumnCount=2};top.ColumnStyles.Add(new(SizeType.Percent,80));top.ColumnStyles.Add(new(SizeType.Percent,20));var fields=new TableLayoutPanel{Dock=DockStyle.Fill,ColumnCount=4,RowCount=3};for(int i=0;i<4;i++)fields.ColumnStyles.Add(new(SizeType.Percent,25));for(int i=0;i<3;i++)fields.RowStyles.Add(new(SizeType.Percent,33));Add(fields,"Mã sách",id,0,0);Add(fields,"Tên sách",title,1,0);Add(fields,"Tác giả",author,2,0);Add(fields,"Thể loại",category,3,0);Add(fields,"Số lượng",qty,0,1);Add(fields,"Đơn giá",price,1,1);fields.Controls.Add(Btn("Thêm sách",(_,_)=>AddBook()),2,1);fields.Controls.Add(Btn("Sửa",(_,_)=>UpdateBook()),3,1);fields.Controls.Add(Btn("Xóa",(_,_)=>DeleteBook()),2,2);fields.Controls.Add(Btn("Làm mới",(_,_)=>Clear()),3,2);top.Controls.Add(fields,0,0);var cp=new FlowLayoutPanel{Dock=DockStyle.Fill,FlowDirection=FlowDirection.TopDown};cp.Controls.Add(cover);cp.Controls.Add(Btn("Tải ảnh bìa",(_,_)=>ChooseCover()));top.Controls.Add(cp,1,0);root.Controls.Add(top,0,0);var bottom=new TableLayoutPanel{Dock=DockStyle.Fill,RowCount=2};bottom.RowStyles.Add(new(SizeType.Absolute,38));bottom.RowStyles.Add(new(SizeType.Percent,100));var s=new FlowLayoutPanel{Dock=DockStyle.Fill};s.Controls.Add(new Label{Text="Tìm kiếm:",AutoSize=true,Padding=new Padding(0,8,0,0)});search.Width=300;search.TextChanged+=(_,_)=>ApplySearch();s.Controls.Add(search);bottom.Controls.Add(s,0,0);grid.Dock=DockStyle.Fill;grid.AutoGenerateColumns=false;grid.SelectionMode=DataGridViewSelectionMode.FullRowSelect;grid.ReadOnly=true;grid.AllowUserToAddRows=false;grid.MultiSelect=false;grid.AutoSizeColumnsMode=DataGridViewAutoSizeColumnsMode.Fill;grid.SelectionChanged+=(_,_)=>LoadRow();Col("Mã sách",nameof(BookModel.BookId));Col("Tên sách",nameof(BookModel.Title));Col("Tác giả",nameof(BookModel.Author));Col("Thể loại",nameof(BookModel.Category));Col("Số lượng",nameof(BookModel.Quantity),"N0");Col("Đơn giá",nameof(BookModel.UnitPrice),"N0");Col("Giá trị",nameof(BookModel.TotalValue),"N0");Col("Ảnh bìa",nameof(BookModel.CoverPath));bottom.Controls.Add(grid,0,1);root.Controls.Add(bottom,0,1);}
void Add(TableLayoutPanel t,string label,Control c,int x,int y){var p=new Panel{Dock=DockStyle.Fill,Padding=new Padding(4)};var s=new TableLayoutPanel{Dock=DockStyle.Fill,RowCount=2};s.RowStyles.Add(new(SizeType.Absolute,23));s.RowStyles.Add(new(SizeType.Percent,100));s.Controls.Add(new Label{Text=label,Dock=DockStyle.Fill},0,0);c.Dock=DockStyle.Fill;s.Controls.Add(c,0,1);p.Controls.Add(s);t.Controls.Add(p,x,y);}Button Btn(string text,EventHandler e){var b=new Button{Text=text,Width=125,Height=30,Margin=new Padding(3)};b.Click+=e;return b;}void Col(string h,string p,string? f=null){var c=new DataGridViewTextBoxColumn{HeaderText=h,DataPropertyName=p};if(f!=null)c.DefaultCellStyle.Format=f;grid.Columns.Add(c);}
bool Valid(){ep.Clear();bool ok=true;if(string.IsNullOrWhiteSpace(id.Text)){ep.SetError(id,"Nhập mã sách.");ok=false;}if(string.IsNullOrWhiteSpace(title.Text)){ep.SetError(title,"Nhập tên sách.");ok=false;}if(!int.TryParse(qty.Text,out int q)||q<=0){ep.SetError(qty,"Số lượng phải là số nguyên dương.");ok=false;}if(!decimal.TryParse(price.Text,out decimal p)||p<0){ep.SetError(price,"Đơn giá không hợp lệ.");ok=false;}if(books.Any(b=>b.BookId.Equals(id.Text.Trim(),StringComparison.OrdinalIgnoreCase)&&b!=selected)){ep.SetError(id,"Mã sách bị trùng.");ok=false;}return ok;}
void AddBook(){if(!Valid())return;books.Add(new(){BookId=id.Text.Trim(),Title=title.Text.Trim(),Author=author.Text.Trim(),Category=category.Text.Trim(),Quantity=int.Parse(qty.Text),UnitPrice=decimal.Parse(price.Text),CoverPath=coverPath});Clear();ApplySearch();}void UpdateBook(){if(selected==null){MessageBox.Show("Chọn sách cần sửa.");return;}if(!Valid())return;selected.Title=title.Text.Trim();selected.Author=author.Text.Trim();selected.Category=category.Text.Trim();selected.Quantity=int.Parse(qty.Text);selected.UnitPrice=decimal.Parse(price.Text);selected.CoverPath=coverPath;bs.ResetBindings(false);ApplySearch();UpdateStatus();}void DeleteBook(){if(selected==null){MessageBox.Show("Chọn sách cần xóa.");return;}if(MessageBox.Show("Xóa sách đã chọn?","Xác nhận",MessageBoxButtons.YesNo,MessageBoxIcon.Warning)!=DialogResult.Yes)return;books.Remove(selected);Clear();ApplySearch();}
void LoadRow(){if(grid.CurrentRow?.DataBoundItem is not BookModel b)return;selected=b;id.Text=b.BookId;title.Text=b.Title;author.Text=b.Author;category.Text=b.Category;qty.Text=b.Quantity.ToString();price.Text=b.UnitPrice.ToString("0.##");coverPath=b.CoverPath;ShowCover();}void Clear(){selected=null;id.Clear();title.Clear();author.Clear();category.Clear();qty.Clear();price.Clear();coverPath="";cover.Image?.Dispose();cover.Image=null;ep.Clear();grid.ClearSelection();}void ChooseCover(){using var d=new OpenFileDialog{Filter="Ảnh (*.png;*.jpg)|*.png;*.jpg;*.jpeg"};if(d.ShowDialog()!=DialogResult.OK)return;coverPath=d.FileName;ShowCover();}void ShowCover(){cover.Image?.Dispose();cover.Image=null;if(!File.Exists(coverPath))return;try{using var fs=File.OpenRead(coverPath);using var im=Image.FromStream(fs);cover.Image=new Bitmap(im);}catch{MessageBox.Show("Không đọc được ảnh bìa.");}}
void Export(){using var d=new SaveFileDialog{Filter="CSV (*.csv)|*.csv",FileName="DanhSachSach.csv"};if(d.ShowDialog()!=DialogResult.OK)return;using var w=new StreamWriter(d.FileName,false,new UTF8Encoding(true));w.WriteLine("BookId,Title,Author,Category,Quantity,UnitPrice,CoverPath");foreach(var b in books)w.WriteLine(string.Join(",",new[]{b.BookId,b.Title,b.Author,b.Category,b.Quantity.ToString(),b.UnitPrice.ToString(CultureInfo.InvariantCulture),Path.GetFileName(b.CoverPath)}.Select(Csv)));MessageBox.Show("Đã xuất CSV.");}
void Import(){using var d=new OpenFileDialog{Filter="CSV (*.csv)|*.csv"};if(d.ShowDialog()!=DialogResult.OK)return;try{var list=new List<BookModel>();foreach(var line in File.ReadLines(d.FileName,Encoding.UTF8).Skip(1)){if(string.IsNullOrWhiteSpace(line))continue;var v=Parse(line);if(v.Count<7||!int.TryParse(v[4],out int q)||!decimal.TryParse(v[5],NumberStyles.Any,CultureInfo.InvariantCulture,out decimal p))continue;string cp=v[6];if(cp!=""&&!Path.IsPathRooted(cp))cp=Path.Combine(Path.GetDirectoryName(d.FileName)!,cp);list.Add(new(){BookId=v[0],Title=v[1],Author=v[2],Category=v[3],Quantity=q,UnitPrice=p,CoverPath=cp});}books.Clear();foreach(var b in list)books.Add(b);Clear();ApplySearch();MessageBox.Show($"Đã nhập {list.Count} đầu sách.");}catch(Exception ex){MessageBox.Show("Lỗi đọc CSV: "+ex.Message);}}
static string Csv(string s)=>"\""+s.Replace("\"","\"\"")+"\"";static List<string> Parse(string line){var r=new List<string>();var b=new StringBuilder();bool q=false;for(int i=0;i<line.Length;i++){char c=line[i];if(c=='"'){if(q&&i+1<line.Length&&line[i+1]=='"'){b.Append('"');i++;}else q=!q;}else if(c==','&&!q){r.Add(b.ToString());b.Clear();}else b.Append(c);}r.Add(b.ToString());return r;}void ApplySearch(){var q=search.Text.Trim();bs.DataSource=new BindingList<BookModel>(books.Where(b=>q==""||b.BookId.Contains(q,StringComparison.OrdinalIgnoreCase)||b.Title.Contains(q,StringComparison.OrdinalIgnoreCase)||b.Author.Contains(q,StringComparison.OrdinalIgnoreCase)).ToList());grid.DataSource=bs;UpdateStatus();}void UpdateStatus(){count.Text=$"Tổng số đầu sách: {books.Count}";value.Text=$"Tổng giá trị kho: {books.Sum(b=>b.TotalValue):N0} đ";}
}